-- Same finite pool used by the interactive prototype. No numeric suffixes.
BEGIN;
INSERT INTO seminar_names.alias_pool(display_name)
SELECT adjective || ' ' || animal
FROM unnest(ARRAY['수줍은','담대한','부끄럼많은','용감한','다정한','호기심많은','느긋한','명랑한','차분한','씩씩한','상냥한','재빠른','신중한','유쾌한','활발한','든든한','포근한','고요한','빛나는','졸린','행복한','즐거운','기쁜','설레는','따뜻한','시원한','산뜻한','싱그러운','반가운','친절한','멋진','근사한','사려깊은','너그러운','의젓한','꼼꼼한','성실한','부지런한','영리한','슬기로운','당당한','자유로운','평화로운','조용한','장난스러운','꿈꾸는','춤추는','노래하는','여행하는','산책하는','책읽는','생각하는','탐험하는','기다리는','미소짓는','웃음많은','잠꾸러기','낙천적인','적극적인','신나는','솔직한','정다운','발랄한','청명한','해맑은','온화한','순수한','정직한','재치있는','유연한','침착한','대범한']) AS adjectives(adjective)
CROSS JOIN unnest(ARRAY['고양이','사자','원숭이','강아지','토끼','여우','곰','판다','코알라','캥거루','수달','다람쥐','고슴도치','기린','코끼리','호랑이','표범','치타','하마','코뿔소','얼룩말','사슴','순록','낙타','알파카','라마','양','염소','말','조랑말','당나귀','소','물소','들소','늑대','너구리','오소리','두더지','비버','해달','물개','바다사자','바다코끼리','고래','돌고래','범고래','듀공','매너티','펭귄','부엉이','올빼미','참새','제비','까치','까마귀','비둘기','두루미','백조','오리','거위','닭','공작','칠면조','타조','앵무새','홍학','갈매기','독수리','매','물총새','딱따구리','카나리아','벌새','종달새','꿩','메추라기','도마뱀','거북이','악어','개구리','도롱뇽','이구아나','카멜레온','금붕어','잉어','연어','참치','해마','복어','가오리','문어','오징어','해파리','불가사리','게','새우','나비','잠자리','무당벌레','반딧불이']) AS animals(animal)
ON CONFLICT (display_name) DO NOTHING;
COMMIT;
